def dijkstra_shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    previous_nodes = {node: None for node in graph}
    distances[source] = 0

    # Set of nodes to be processed
    nodes_to_process = graph.keys()

    while nodes_to_process:
        # Pick the node with the smallest distance
        current_min_node = min(nodes_to_process, key=lambda node: distances[node])
        nodes_to_process.remove(current_min_node)

        # If we reach the target node, we can stop
        if current_min_node == target:
            break

        for neighbour, weight in graph[current_min_node]:
            path_length = distances[current_min_node] + weight
            if path_length < distances[neighbour]:
                distances[neighbour] = path_length
                previous_nodes[neighbour] = current_min_node

    # Reconstruct the path from source to target
    path = []
    node = target
    while node is not None:
        path.append(node)
        node = previous_nodes[node]
    path.reverse()

    # Calculate the distance
    distance = distances[target] if target in distances else float('inf')

    return (distance, path)

def shortest_path(graph, source, target):
    if source not in graph or target not in graph:
        return (float('inf'), None)

    return dijkstra_shortest_path(graph, source, target)

